def transform(grid):
    h, w = len(grid), len(grid[0])
    full_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    full_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    return [[2 if r in full_rows or c in full_cols else grid[r][c]
             for c in range(w)] for r in range(h)]

